package cli

import (
	"database/sql"
	"path/filepath"
	"testing"

	_ "modernc.org/sqlite"
)

func TestFTS5Probe(t *testing.T) {
	dbPath := filepath.Join(t.TempDir(), "p.sqlite")
	db, err := sql.Open("sqlite", dbPath)
	if err != nil {
		t.Fatal(err)
	}
	defer db.Close()
	if _, err := db.Exec(`CREATE VIRTUAL TABLE h USING fts5(summary, kind UNINDEXED, tokenize='porter unicode61')`); err != nil {
		t.Fatalf("create fts5: %v", err)
	}
	rows := [][2]string{
		{"we decided to use the embedding model for recall", "decision"},
		{"manual commit attribution base drift behavior", "decision"},
		{"just an unrelated note about lunch", "tool_call"},
	}
	for _, r := range rows {
		if _, err := db.Exec(`INSERT INTO h(summary, kind) VALUES (?, ?)`, r[0], r[1]); err != nil {
			t.Fatalf("insert: %v", err)
		}
	}
	q := `SELECT rowid, summary, bm25(h) FROM h WHERE h MATCH ? AND kind = 'decision' ORDER BY bm25(h) LIMIT 5`
