	brainDir := t.TempDir()
	index := ftsTestIndex()

	scored, ok := rankHistoryViaFTS(brainDir, index, "decisions", "reasons we picked one embedding approach over another", 25)
	if !ok {
		t.Fatal("rankHistoryViaFTS returned ok=false; expected BM25 results")
